def solution(bids, budget):
    first_index = {}                         # bid value -> earliest index seen so far
    for j, bid in enumerate(bids):
        need = budget - bid
        if need in first_index:
            return [first_index[need], j]    # first j that completes a pair, earliest partner
        if bid not in first_index:           # keep the earliest index on duplicates
            first_index[bid] = j
    return []

